describe('Change Email Address', () => {
    beforeEach(() => {
        cy.visit('/user_profile');
        cy.login('testuser@example.com', 'password123'); // Assuming a login function exists
    });

    it('should successfully change the email address with confirmation', () => {
        cy.get('input[name="email"]').clear().type('newemail@example.com');
        cy.get('button[type="submit"]').click();
        cy.get('.confirmation-modal').should('be.visible');
        cy.get('.confirmation-modal button.confirm').click();
        cy.get('.success-message').should('contain', 'Email address changed successfully');
        cy.get('input[name="email"]').should('have.value', 'newemail@example.com');
    });

    it('should show an error when the email address is invalid', () => {
        cy.get('input[name="email"]').clear().type('invalid-email');
        cy.get('button[type="submit"]').click();
        cy.get('.error-message').should('be.visible').and('contain', 'Please enter a valid email address');
    });
});
